def enhanced_filter_with_trend_preservation(x, window_size=20):
    """Centered polynomial smoothing with robust weak one- and two-sample reversal rejection."""
    if len(x) < window_size:
        raise ValueError(f"Input signal length ({len(x)}) must be >= window_size ({window_size})")

    x = np.asarray(x, dtype=float)
    if window_size == 1:
        return x.copy()

    # Centered polynomial smoothing preserves curvature without accumulating
    # the centroid delay of a trailing moving average.
    span = min(9, window_size if window_size % 2 else window_size - 1)
    if span < 3:
        smoothed = x.copy()
    else:
        smoothed = savgol_filter(
            x, span, min(3 if span >= 5 else 2, span - 1), mode="interp"
        )

    # Scale reversal thresholds from derivative MAD, making the decision robust
    # to changing noise level and signal amplitude.
    d = np.diff(smoothed)
    if d.size >= 3:
        scale = 1.4826 * np.median(np.abs(d - np.median(d))) + 1e-12

        # Flatten isolated weak zig-zags using the chord between neighbors.
        flip = (d[:-2] * d[1:-1] < 0.0) & (d[1:-1] * d[2:] < 0.0)
        indices = np.flatnonzero(
            flip & (np.abs(d[1:-1]) < 2.5 * scale)
        ) + 1
        if indices.size:
            smoothed[indices] = 0.5 * (
                smoothed[indices - 1] + smoothed[indices + 1]
            )

        # A weak two-derivative move opposite to both adjacent directions
        # creates a false reversal pair. Replace it with its endpoint chord;
        # longer or stronger turns remain genuine resolved dynamics.
        d = np.diff(smoothed)
        if d.size >= 4:
            turn = (
                (d[:-3] * d[1:-2] < 0.0)
                & (d[1:-2] * d[2:-1] > 0.0)
                & (d[2:-1] * d[3:] < 0.0)
            )
            weak = np.maximum(np.abs(d[1:-2]), np.abs(d[2:-1])) < 1.5 * scale
            for j in np.flatnonzero(turn & weak):
                smoothed[j + 1:j + 4] = np.linspace(
                    smoothed[j], smoothed[j + 4], 5
                )[1:4]

    return smoothed[window_size - 1:]
